SELECT cc.cc_state, cc.cc_call_center_id, cc.cc_name, cc.cc_employees, w.w_warehouse_id, w.w_city, SUM(cs.cs_net_profit) AS total_net_profit, SUM(cs.cs_ext_sales_price) AS total_sales, CASE WHEN cc.cc_employees > 0 THEN SUM(cs.cs_net_profit) / cc.cc_employees ELSE 0 END AS profit_per_employee, DENSE_RANK() OVER (PARTITION BY cc.cc_state ORDER BY CASE WHEN cc.cc_employees > 0 THEN SUM(cs.cs_net_profit) / cc.cc_employees ELSE 0 END DESC) AS state_profit_employee_rank, COUNT(DISTINCT p.p_promo_id) AS promotion_count, CASE WHEN MAX(CASE WHEN p.p_discount_active = 'Y' THEN 1 ELSE 0 END) = 1 THEN 'Active Discount' ELSE 'No Active Discount' END AS discount_status FROM catalog_sales cs JOIN call_center cc ON cs.cs_call_center_sk = cc.cc_call_center_sk JOIN warehouse w ON cs.cs_warehouse_sk = w.w_warehouse_sk LEFT JOIN promotion p ON cs.cs_promo_sk = p.p_promo_sk GROUP BY cc.cc_state, cc.cc_call_center_id, cc.cc_name, cc.cc_employees, w.w_warehouse_id, w.w_city HAVING SUM(cs.cs_ext_sales_price) > 20000 ORDER BY cc.cc_state, state_profit_employee_rank
